-- 0.4 Kolom T_GENERAL_POLIS NB-151032 (semua kolom migrasi 182-255). DIPERTAHANKAN apa adanya - skrip TIDAK mengubahnya.
-- ⚠️ Untuk keputusan work owner ("kaya baru dibuat"): kolom yang men-cache isi tab yang dihapus, kandidat dikosongkan -
--    PERCENT_SHARE (Spreading), SHARE_CEDANT_TYPE (Cedant), PPN_CHECK / PAY_RI_COMMISION / PAY_PCT_BROKERAGE_FEE (Premium
--    Deduction), PAY_INSTALLMENT (Payment), PRO_RATE_PERCENT (Coverage Aneka), dan kolom alur Submit NB_STATUS,
--    IS_DEDUCTIBLE_ACCEPTANCE, COMMENT_DEDUCTIBLE, DATE_TO_UW, SUBMIT_TO_UW, DAYS_VALIDITY, DATE_VALIDITY, WAITING_BIND_DATE,
--    COMMENT_TEXT, CONFIRM_BINDING, RECEIVED_RI_SLIP. START_DATE_TIME / END_DATE_TIME / OFFERING_DATE (tab General) DITIMPA
--    Save Data CSV yang salah sasaran (header CSV / tanggal Save) - nilai aslinya tidak ada di skrip ini.
SELECT ID, IDPEGA, COB_GROUP, START_DATE_TIME, OFFERING_DATE, END_DATE_TIME, FOLLOWING, PERCENT_SHARE, SHARE_CEDANT_TYPE,
       PPN_CHECK, PAY_RI_COMMISION, PAY_PCT_BROKERAGE_FEE, PAY_INSTALLMENT, NB_STATUS, IS_DEDUCTIBLE_ACCEPTANCE,
       COMMENT_DEDUCTIBLE, DATE_TO_UW, SUBMIT_TO_UW, DAYS_VALIDITY, DATE_VALIDITY, WAITING_BIND_DATE, COMMENT_TEXT,
       CONFIRM_BINDING, RECEIVED_RI_SLIP, PRO_RATE_PERCENT
  FROM {skema}.T_GENERAL_POLIS WHERE ID = 'NB-151032';
