-- men-cache tab Cedant (kandidat dikosongkan, keputusan work owner).
SELECT * FROM {skema}.T_QUOTATIONDATA WHERE PARENT_ID = 'NB-151032';

-- 0.5 Tabel Pega / POOLDATA yang ditulis nbfacin untuk case - TIDAK DIHAPUS, hanya dihitung (kunci dari kode repository:
-- IDPEGA / ID_PEGA = 'NB-151032'; M_RISK_LOSS_PROFILE lewat NOPOLIS JSON_POLIS case).
SELECT 'DOCUMENT_POLIS (lampiran)' TABEL, COUNT(*) JUMLAH FROM {skema}.DOCUMENT_POLIS WHERE IDPEGA = 'NB-151032'
UNION ALL SELECT 'JSON_OFFER', COUNT(*) FROM {skema}.JSON_OFFER WHERE IDPEGA = 'NB-151032'
UNION ALL SELECT 'FACINOFFER', COUNT(*) FROM {skema}.FACINOFFER WHERE IDPEGA = 'NB-151032'
UNION ALL SELECT 'JSON_POLIS', COUNT(*) FROM {skema}.JSON_POLIS WHERE IDPEGA = 'NB-151032'
UNION ALL SELECT 'FACINPRODUCTION', COUNT(*) FROM {skema}.FACINPRODUCTION WHERE IDPEGA = 'NB-151032'
UNION ALL SELECT 'CEDING_FACINPRODUCTION', COUNT(*) FROM {skema}.CEDING_FACINPRODUCTION WHERE IDPEGA = 'NB-151032'
UNION ALL SELECT 'M_RISK_LOSS_PROFILE', COUNT(*) FROM {skema}.M_RISK_LOSS_PROFILE
           WHERE NOPOLIS IN (SELECT j.NOPOLIS FROM {skema}.JSON_POLIS j WHERE j.IDPEGA = 'NB-151032')
UNION ALL SELECT 'HISTORYAKSEPTASIPRODUCTION', COUNT(*) FROM {skema}.HISTORYAKSEPTASIPRODUCTION WHERE IDPEGA = 'NB-151032'
UNION ALL SELECT 'HISTORYAKSEPTASIPEGA', COUNT(*) FROM {skema}.HISTORYAKSEPTASIPEGA WHERE ID_PEGA = 'NB-151032'
UNION ALL SELECT 'FACINPERFORMANCE', COUNT(*) FROM {skema}.FACINPERFORMANCE WHERE IDPEGA = 'NB-151032';
