-- =====================================================================================================================
-- BAGIAN 1A - HAPUS, SATU TRANSAKSI (TANPA COMMIT). Gagal di tengah -> seluruh blok batal.
-- =====================================================================================================================
-- SET SERVEROUTPUT ON   (perintah SQL*Plus - hanya untuk SQL*Plus / SQL Developer F5; di aplikasi lain hapus baris ini dan aktifkan panel "DBMS Output")
DECLARE
  v_kasus CONSTANT VARCHAR2(32) := 'NB-151032';
  v_n     NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_n FROM {skema}.T_WORK_POLIS WHERE ID = v_kasus AND LINI = 'FAC';
  IF v_n <> 1 THEN RAISE_APPLICATION_ERROR(-20001, 'NB-151032 tidak ada di T_WORK_POLIS LINI FAC'); END IF;
  SELECT COUNT(*) INTO v_n FROM {skema}.T_NB_OPPORTUNITY WHERE ID = v_kasus AND UPPER(TRIM(CLASS_OF_BUSINESS)) = 'MARINE CARGO';
  IF v_n <> 1 THEN RAISE_APPLICATION_ERROR(-20002, 'CLASS_OF_BUSINESS NB-151032 bukan MARINE CARGO - periksa 0.1'); END IF;
  SELECT COUNT(*) INTO v_n FROM {skema}.T_NB_CSV_UNGGAH WHERE CASE_ID = v_kasus AND STATUS IN ('memvalidasi', 'menyimpan');
  IF v_n <> 0 THEN RAISE_APPLICATION_ERROR(-20003, 'ada pekerjaan unggah CSV berjalan di NB-151032'); END IF;

  -- Marine Cargo (sqlHapusCargo)
  DELETE FROM {skema}.T_SPREADINGLIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_CARGOLIST' AND v.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DBMS_OUTPUT.PUT_LINE('T_SPREADINGLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_DEDUCTIBLELIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_CARGOLIST' AND v.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DBMS_OUTPUT.PUT_LINE('T_DEDUCTIBLELIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_ADDITIONALCOVERAGE WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_CARGOLIST' AND v.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DBMS_OUTPUT.PUT_LINE('T_ADDITIONALCOVERAGE: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_COVERAGELIST WHERE PARENT_TABLE = 'T_CARGOLIST' AND PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_COVERAGELIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_ADDITIONALSHIP WHERE PARENT_ID IN (SELECT s.ID FROM {skema}.T_SHIP s WHERE s.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DBMS_OUTPUT.PUT_LINE('T_ADDITIONALSHIP: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_SHIP WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_SHIP: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_LC WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_LC: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_SURVEYAGENT WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_SURVEYAGENT: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_CARGOLIST WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_CARGOLIST: ' || SQL%ROWCOUNT);

  -- coverage objek Aneka (ber-induk T_ANEKALIST, tanpa FK)
  DELETE FROM {skema}.T_SPREADINGLIST WHERE PARENT_ID IN (SELECT c.ID FROM {skema}.T_COVERAGELIST c WHERE c.PARENT_TABLE = 'T_ANEKALIST' AND c.PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))));
  DBMS_OUTPUT.PUT_LINE('T_SPREADINGLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_DEDUCTIBLELIST WHERE PARENT_ID IN (SELECT c.ID FROM {skema}.T_COVERAGELIST c WHERE c.PARENT_TABLE = 'T_ANEKALIST' AND c.PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))));
  DBMS_OUTPUT.PUT_LINE('T_DEDUCTIBLELIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_COVERAGELIST WHERE PARENT_TABLE = 'T_ANEKALIST' AND PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DBMS_OUTPUT.PUT_LINE('T_COVERAGELIST: ' || SQL%ROWCOUNT);

  -- objek Aneka (sqlHapusAneka) - sebelum lokasi FIRE dihapus
  DELETE FROM {skema}.T_MEMORANDUMACCEPT WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DBMS_OUTPUT.PUT_LINE('T_MEMORANDUMACCEPT: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_VEHICLEHE WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DBMS_OUTPUT.PUT_LINE('T_VEHICLEHE: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_AVIATIONHULL WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DBMS_OUTPUT.PUT_LINE('T_AVIATIONHULL: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_MARINEHULL WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DBMS_OUTPUT.PUT_LINE('T_MARINEHULL: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_ANEKALIST WHERE ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DBMS_OUTPUT.PUT_LINE('T_ANEKALIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_OCCUPATIONLIST: ' || SQL%ROWCOUNT);

  -- objek FIRE (sqlHapusObjek) - ±1 juta lokasi
  DELETE FROM {skema}.T_COINSDATA WHERE PARENT_ID IN (SELECT c.ID FROM {skema}.T_LISTCAUSEOFLOSS c WHERE c.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus));
  DBMS_OUTPUT.PUT_LINE('T_COINSDATA: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_LISTCAUSEOFLOSS WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_LISTCAUSEOFLOSS: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_TABLEOFLIMIT WHERE PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_PROPERTY' AND o.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus));
  DBMS_OUTPUT.PUT_LINE('T_TABLEOFLIMIT: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_PROPERTY' AND o.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_OCCUPATIONLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_DEDUCTIBLELIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v JOIN {skema}.T_PROPERTYITEMLIST i ON i.ID = v.PARENT_ID JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_DEDUCTIBLELIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_SPREADINGLIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v JOIN {skema}.T_PROPERTYITEMLIST i ON i.ID = v.PARENT_ID JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_SPREADINGLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND v.PARENT_ID IN (SELECT i.ID FROM {skema}.T_PROPERTYITEMLIST i JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_COVERAGELIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_PROPERTYITEMLIST WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_PROPERTYITEMLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_RISKLOCATION WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_RISKLOCATION: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_BUILDINGCONSTRUCTION WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_BUILDINGCONSTRUCTION: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_SURROUNDINGRISK WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_SURROUNDINGRISK: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_PROPERTY WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_PROPERTY: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_FEALIST WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_FEALIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_LOCATIONLIST: ' || SQL%ROWCOUNT);

  -- CurrencyList + cicilan
  DELETE FROM {skema}.T_LISTINSTALLMENT WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_CURRENCYLIST WHERE PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_LISTINSTALLMENT: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_CURRENCYLIST WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_CURRENCYLIST: ' || SQL%ROWCOUNT);

  -- Cedant Panels
  DELETE FROM {skema}.T_CEDINGCEDANTLIST WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_CEDINGCEDANTLIST: ' || SQL%ROWCOUNT);

  -- Clauses
  DELETE FROM {skema}.T_CLAUSELIST WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_CLAUSELIST: ' || SQL%ROWCOUNT);

  -- Scoring Risk
  DELETE FROM {skema}.T_SCORING_OPTION WHERE PARENT_ID IN (SELECT f.ID FROM {skema}.T_SCORING_FACTOR f WHERE f.PARENT_ID IN (SELECT d.ID FROM {skema}.T_DATASCORINGRISKLIST d WHERE d.PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus)));
  DBMS_OUTPUT.PUT_LINE('T_SCORING_OPTION: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_SCORING_FACTOR WHERE PARENT_ID IN (SELECT d.ID FROM {skema}.T_DATASCORINGRISKLIST d WHERE d.PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus));
  DBMS_OUTPUT.PUT_LINE('T_SCORING_FACTOR: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_DATASCORINGRISKLIST WHERE PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_DATASCORINGRISKLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_SCORINGRESULT WHERE PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_SCORINGRESULT: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_SCORINGRISK WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_SCORINGRISK: ' || SQL%ROWCOUNT);

  -- Loss Record
  DELETE FROM {skema}.T_LOSSRECORDLIST WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_LOSSRECORD k WHERE k.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_LOSSRECORDLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_LOSSRECORD WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_LOSSRECORD: ' || SQL%ROWCOUNT);

  -- Correspondence (SEMUA baris case, termasuk yang sudah terkirim)
  DELETE FROM {skema}.T_RECIPIENTLIST WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CORRESPONDENCELIST k WHERE k.PARENT_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_RECIPIENTLIST: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_CORRESPONDENCELIST WHERE PARENT_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_CORRESPONDENCELIST: ' || SQL%ROWCOUNT);

  -- pekerjaan unggah CSV
  DELETE FROM {skema}.T_NB_CSV_PESAN WHERE UNGGAH_ID IN (SELECT u.ID FROM {skema}.T_NB_CSV_UNGGAH u WHERE u.CASE_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_NB_CSV_PESAN: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_NB_CSV_BARIS WHERE UNGGAH_ID IN (SELECT u.ID FROM {skema}.T_NB_CSV_UNGGAH u WHERE u.CASE_ID = v_kasus);
  DBMS_OUTPUT.PUT_LINE('T_NB_CSV_BARIS: ' || SQL%ROWCOUNT);
  DELETE FROM {skema}.T_NB_CSV_UNGGAH WHERE CASE_ID = v_kasus;
  DBMS_OUTPUT.PUT_LINE('T_NB_CSV_UNGGAH: ' || SQL%ROWCOUNT);
  DBMS_OUTPUT.PUT_LINE('SELESAI - BELUM COMMIT: jalankan BAGIAN 2, lalu COMMIT atau ROLLBACK');
END;
/


-- =====================================================================================================================
-- BAGIAN 1B - HAPUS BERTAHAP (pilihan DBA bila undo tidak cukup). ⚠️ COMMIT per potongan: TIDAK atomik - bila berhenti di
-- tengah, sebagian sudah terhapus; blok AMAN dijalankan ulang (setiap pernyataan hanya menghapus yang tersisa). Objek FIRE
-- dihapus per rentang SEQ_NO lokasi (v_potong lokasi per COMMIT); baris penampung CSV per rentang NO_BARIS.
-- =====================================================================================================================
DECLARE
  v_kasus  CONSTANT VARCHAR2(32) := 'NB-151032';
  v_potong CONSTANT NUMBER := 10000;
  v_n      NUMBER;
  v_dari   NUMBER;
  v_sampai NUMBER;
  v_maks   NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_n FROM {skema}.T_WORK_POLIS WHERE ID = v_kasus AND LINI = 'FAC';
  IF v_n <> 1 THEN RAISE_APPLICATION_ERROR(-20001, 'NB-151032 tidak ada di T_WORK_POLIS LINI FAC'); END IF;
  SELECT COUNT(*) INTO v_n FROM {skema}.T_NB_OPPORTUNITY WHERE ID = v_kasus AND UPPER(TRIM(CLASS_OF_BUSINESS)) = 'MARINE CARGO';
  IF v_n <> 1 THEN RAISE_APPLICATION_ERROR(-20002, 'CLASS_OF_BUSINESS NB-151032 bukan MARINE CARGO - periksa 0.1'); END IF;
  SELECT COUNT(*) INTO v_n FROM {skema}.T_NB_CSV_UNGGAH WHERE CASE_ID = v_kasus AND STATUS IN ('memvalidasi', 'menyimpan');
  IF v_n <> 0 THEN RAISE_APPLICATION_ERROR(-20003, 'ada pekerjaan unggah CSV berjalan di NB-151032'); END IF;

  -- Marine Cargo (sqlHapusCargo) (kecil, sekali)
  DELETE FROM {skema}.T_SPREADINGLIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_CARGOLIST' AND v.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DELETE FROM {skema}.T_DEDUCTIBLELIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_CARGOLIST' AND v.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DELETE FROM {skema}.T_ADDITIONALCOVERAGE WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_CARGOLIST' AND v.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DELETE FROM {skema}.T_COVERAGELIST WHERE PARENT_TABLE = 'T_CARGOLIST' AND PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_ADDITIONALSHIP WHERE PARENT_ID IN (SELECT s.ID FROM {skema}.T_SHIP s WHERE s.PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus));
  DELETE FROM {skema}.T_SHIP WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_LC WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_SURVEYAGENT WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CARGOLIST k WHERE k.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_CARGOLIST WHERE PARENT_ID = v_kasus;

  -- coverage objek Aneka (ber-induk T_ANEKALIST, tanpa FK) (kecil, sekali)
  DELETE FROM {skema}.T_SPREADINGLIST WHERE PARENT_ID IN (SELECT c.ID FROM {skema}.T_COVERAGELIST c WHERE c.PARENT_TABLE = 'T_ANEKALIST' AND c.PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))));
  DELETE FROM {skema}.T_DEDUCTIBLELIST WHERE PARENT_ID IN (SELECT c.ID FROM {skema}.T_COVERAGELIST c WHERE c.PARENT_TABLE = 'T_ANEKALIST' AND c.PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))));
  DELETE FROM {skema}.T_COVERAGELIST WHERE PARENT_TABLE = 'T_ANEKALIST' AND PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));

  -- objek Aneka (sqlHapusAneka) - sebelum lokasi FIRE dihapus (kecil, sekali)
  DELETE FROM {skema}.T_MEMORANDUMACCEPT WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DELETE FROM {skema}.T_VEHICLEHE WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DELETE FROM {skema}.T_AVIATIONHULL WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DELETE FROM {skema}.T_MARINEHULL WHERE PARENT_ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DELETE FROM {skema}.T_ANEKALIST WHERE ID IN (SELECT a.ID FROM {skema}.T_ANEKALIST a WHERE (a.PARENT_TABLE = 'T_OCCUPATIONLIST' AND a.PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus))) OR (a.PARENT_TABLE = 'T_RISKLOCATION' AND a.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus)));
  DELETE FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_RISKLOCATION' AND o.PARENT_ID IN (SELECT r.ID FROM {skema}.T_RISKLOCATION r JOIN {skema}.T_PROPERTY p ON p.ID = r.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  COMMIT;

  -- objek FIRE per rentang SEQ_NO lokasi
  SELECT NVL(MAX(SEQ_NO), 0) INTO v_maks FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus;
  v_dari := 1;
  WHILE v_dari <= v_maks LOOP
    v_sampai := v_dari + v_potong - 1;
    DELETE FROM {skema}.T_COINSDATA WHERE PARENT_ID IN (SELECT c.ID FROM {skema}.T_LISTCAUSEOFLOSS c WHERE c.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai));
    DELETE FROM {skema}.T_LISTCAUSEOFLOSS WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_TABLEOFLIMIT WHERE PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_PROPERTY' AND o.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai));
    DELETE FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_PROPERTY' AND o.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_DEDUCTIBLELIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v JOIN {skema}.T_PROPERTYITEMLIST i ON i.ID = v.PARENT_ID JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_SPREADINGLIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v JOIN {skema}.T_PROPERTYITEMLIST i ON i.ID = v.PARENT_ID JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND v.PARENT_ID IN (SELECT i.ID FROM {skema}.T_PROPERTYITEMLIST i JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_PROPERTYITEMLIST WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_RISKLOCATION WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_BUILDINGCONSTRUCTION WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_SURROUNDINGRISK WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus AND l.SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_PROPERTY WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus AND SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_FEALIST WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus AND SEQ_NO BETWEEN v_dari AND v_sampai);
    DELETE FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus AND SEQ_NO BETWEEN v_dari AND v_sampai;
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('lokasi SEQ_NO ' || v_dari || '-' || v_sampai || ' selesai');
    v_dari := v_sampai + 1;
  END LOOP;
  -- sisa lokasi FIRE di luar rentang (mis. SEQ_NO NULL / tidak terduga): sekali lagi tanpa rentang
  DELETE FROM {skema}.T_COINSDATA WHERE PARENT_ID IN (SELECT c.ID FROM {skema}.T_LISTCAUSEOFLOSS c WHERE c.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus));
  DELETE FROM {skema}.T_LISTCAUSEOFLOSS WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_TABLEOFLIMIT WHERE PARENT_ID IN (SELECT o.ID FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_PROPERTY' AND o.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus));
  DELETE FROM {skema}.T_OCCUPATIONLIST o WHERE o.PARENT_TABLE = 'T_PROPERTY' AND o.PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_DEDUCTIBLELIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v JOIN {skema}.T_PROPERTYITEMLIST i ON i.ID = v.PARENT_ID JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_SPREADINGLIST WHERE PARENT_ID IN (SELECT v.ID FROM {skema}.T_COVERAGELIST v JOIN {skema}.T_PROPERTYITEMLIST i ON i.ID = v.PARENT_ID JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_COVERAGELIST v WHERE v.PARENT_TABLE = 'T_PROPERTYITEMLIST' AND v.PARENT_ID IN (SELECT i.ID FROM {skema}.T_PROPERTYITEMLIST i JOIN {skema}.T_PROPERTY p ON p.ID = i.PARENT_ID JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_PROPERTYITEMLIST WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_RISKLOCATION WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_BUILDINGCONSTRUCTION WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_SURROUNDINGRISK WHERE PARENT_ID IN (SELECT p.ID FROM {skema}.T_PROPERTY p JOIN {skema}.T_LOCATIONLIST l ON l.ID = p.PARENT_ID WHERE l.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_PROPERTY WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_FEALIST WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_LOCATIONLIST WHERE PARENT_ID = v_kasus;
  COMMIT;

  -- CurrencyList + cicilan
  DELETE FROM {skema}.T_LISTINSTALLMENT WHERE PARENT_ID IN (SELECT ID FROM {skema}.T_CURRENCYLIST WHERE PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_CURRENCYLIST WHERE PARENT_ID = v_kasus;

  -- Cedant Panels
  DELETE FROM {skema}.T_CEDINGCEDANTLIST WHERE PARENT_ID = v_kasus;

  -- Clauses
  DELETE FROM {skema}.T_CLAUSELIST WHERE PARENT_ID = v_kasus;

  -- Scoring Risk
  DELETE FROM {skema}.T_SCORING_OPTION WHERE PARENT_ID IN (SELECT f.ID FROM {skema}.T_SCORING_FACTOR f WHERE f.PARENT_ID IN (SELECT d.ID FROM {skema}.T_DATASCORINGRISKLIST d WHERE d.PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus)));
  DELETE FROM {skema}.T_SCORING_FACTOR WHERE PARENT_ID IN (SELECT d.ID FROM {skema}.T_DATASCORINGRISKLIST d WHERE d.PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus));
  DELETE FROM {skema}.T_DATASCORINGRISKLIST WHERE PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_SCORINGRESULT WHERE PARENT_ID IN (SELECT s.ID FROM {skema}.T_SCORINGRISK s WHERE s.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_SCORINGRISK WHERE PARENT_ID = v_kasus;

  -- Loss Record
  DELETE FROM {skema}.T_LOSSRECORDLIST WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_LOSSRECORD k WHERE k.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_LOSSRECORD WHERE PARENT_ID = v_kasus;

  -- Correspondence (SEMUA baris case, termasuk yang sudah terkirim)
  DELETE FROM {skema}.T_RECIPIENTLIST WHERE PARENT_ID IN (SELECT k.ID FROM {skema}.T_CORRESPONDENCELIST k WHERE k.PARENT_ID = v_kasus);
  DELETE FROM {skema}.T_CORRESPONDENCELIST WHERE PARENT_ID = v_kasus;
  COMMIT;

  -- pekerjaan unggah CSV: penampung baris per rentang NO_BARIS
  SELECT NVL(MAX(b.NO_BARIS), 0) INTO v_maks FROM {skema}.T_NB_CSV_BARIS b
   WHERE b.UNGGAH_ID IN (SELECT u.ID FROM {skema}.T_NB_CSV_UNGGAH u WHERE u.CASE_ID = v_kasus);
  v_dari := 1;
  WHILE v_dari <= v_maks LOOP
    v_sampai := v_dari + v_potong * 10 - 1;
    DELETE FROM {skema}.T_NB_CSV_BARIS WHERE NO_BARIS BETWEEN v_dari AND v_sampai
       AND UNGGAH_ID IN (SELECT u.ID FROM {skema}.T_NB_CSV_UNGGAH u WHERE u.CASE_ID = v_kasus);
    COMMIT;
    v_dari := v_sampai + 1;
  END LOOP;
  DELETE FROM {skema}.T_NB_CSV_PESAN WHERE UNGGAH_ID IN (SELECT u.ID FROM {skema}.T_NB_CSV_UNGGAH u WHERE u.CASE_ID = v_kasus);
  DELETE FROM {skema}.T_NB_CSV_BARIS WHERE UNGGAH_ID IN (SELECT u.ID FROM {skema}.T_NB_CSV_UNGGAH u WHERE u.CASE_ID = v_kasus);
  DELETE FROM {skema}.T_NB_CSV_UNGGAH WHERE CASE_ID = v_kasus;
  COMMIT;
  DBMS_OUTPUT.PUT_LINE('SELESAI (sudah COMMIT per potongan) - jalankan BAGIAN 2');
END;
/


-- =====================================================================================================================
-- BAGIAN 2 - CEK SESUDAH. Harapan: semua tabel 0, KECUALI lima baris "(DIPERTAHANKAN)" = angka BAGIAN 0.3. 0.4 / 0.5 tidak
-- berubah.
